H('392.d.3.B',4,"A chart that shows tasks as horizontal bars over time is a:","Gantt chart",["pie chart","schematic","bar code"],"Gantt charts plot tasks against time.")
H('392.d.3.C',3,"In a simulated electronics enterprise, students may take roles such as:","production manager",["astronaut","movie star","pilot"],"Simulated companies mirror real job roles.")
H('392.d.3.C',4,"Running a school business that builds and sells kits helps students learn:","how companies operate",["nothing about business","only drawing","only reading"],"Real or simulated enterprises teach business operations.")
H('392.d.3.D',3,"A production plan for a single circuit project should list:","materials, steps, and time needed",["only the color","only the name","just the team"],"A plan covers what, how, and when.")
H('392.d.3.D',4,"A bill of materials in a production plan lists:","every part needed",["employee pay","safety quiz scores","customer names"],"A BOM itemizes all components.")

H('392.d.4.A',3,"A student must score 100% on an electrical safety test before:","using soldering equipment",["entering the cafeteria","using a pencil","reading the book"],"Safety tests gate access to hazardous tools.")
H('392.d.4.A',4,"Electronics safety tests are repeated each term so students stay:","alert to hazards",["distracted","unprepared","untested"],"Repetition reinforces safe habits.")
H('392.d.4.B',3,"Before operating an unfamiliar oscilloscope, you should read:","the operator's manual",["a novel","the cafeteria menu","a news website"],"Manuals give safe operating procedures.")
H('392.d.4.B',4,"Where would you look to find a machine's required lockout procedure?","The equipment instruction manual",["The school yearbook","A cookbook","A phone book"],"Manuals describe lockout steps.")
H('392.d.4.C',3,"Which U.S. agency sets and enforces workplace safety rules?","OSHA",["NASA","FBI","NFL"],"OSHA regulates workplace safety.")
H('392.d.4.C',4,"Employers are required by OSHA to provide workers with:","a workplace free from recognized hazards",["unlimited breaks","free tools to keep","guaranteed bonuses"],"The General Duty Clause requires hazard-free workplaces.")
H('392.d.4.D',3,"Lead-based solder is a hazard because lead is a:","toxic metal",["safe mineral","food additive","water filter"],"Lead harms the body.")
H('392.d.4.D',4,"The OSHA Hazard Communication Standard requires chemical containers to have:","hazard labels",["bright colors only","advertisements","price tags only"],"Labels communicate chemical hazards.")
H('392.d.4.E',3,"Old circuit boards and batteries should be disposed of through:","an e-waste recycling program",["a storm drain","a creek","a backyard fire"],"E-waste contains toxic metals.")
H('392.d.4.E',4,"Used flux and solder scraps should be placed in:","a designated waste container",["a lunch bag","a pocket","a classmate's desk"],"Scraps go in labeled waste containers.")
H('392.d.4.F',3,"A soldering iron tip should be cleaned and:","tinned",["bent","painted","dropped"],"Tinning protects the tip and improves heat transfer.")
H('392.d.4.F',4,"Regular calibration of a meter ensures its readings stay:","accurate",["decorative","louder","random"],"Calibration keeps measurements correct.")
H('392.d.4.G',3,"Static-sensitive parts should be stored in:","anti-static bags",["any open bin","a wet cloth","a coat pocket"],"Anti-static bags protect ICs from ESD.")
H('392.d.4.G',4,"After use, a soldering iron should be returned to its:","stand",["pocket","backpack","drawer while hot"],"Hot irons belong in their holder.")
H('392.d.4.H',3,"A frayed power cord on a test instrument that is not repaired could cause:","an electric shock",["cleaner signals","longer battery life","a quieter lab"],"Damaged insulation exposes live conductors.")
H('392.d.4.H',4,"An uncalibrated meter used in repairs can lead to:","wrong measurements and faulty repairs",["perfect results","lower bills","fewer tests"],"Bad readings cause bad repairs.")

H('392.d.5.A',3,"Direct current (DC) flows:","in one direction only",["back and forth","in circles only","only in water"],"DC does not reverse direction.")
H('392.d.5.A',4,"Which source produces DC?","A battery",["A wall outlet","A power-line transformer","A household generator"],"Batteries supply steady DC.")
H('392.d.5.B',3,"In an atom, electrons carry a:","negative charge",["positive charge","no charge","double charge"],"Electrons are negatively charged.")
H('392.d.5.B',4,"Materials with loosely bound outer electrons make good:","conductors",["insulators","dividers","filters"],"Free electrons carry current easily.")
H('392.d.5.C',3,"A zigzag line on a schematic usually represents a:","resistor",["capacitor","battery","switch"],"The zigzag is the resistor symbol.")
H('392.d.5.C',4,"On a schematic, a line that crosses another with a dot at the crossing indicates the wires are:","connected",["separate","broken","insulated"],"A junction dot means electrical connection.")
H('392.d.5.D',3,"A switch in a circuit is used to:","open or close the current path",["raise voltage","store charge","produce light"],"Switches control current flow.")
H('392.d.5.D',4,"In a circuit, the ground is a:","common reference point for voltage",["source of current","type of resistor","fuse"],"Ground is the 0 V reference.")
H('392.d.5.E',3,"A resistor with bands brown, black, red has a value of:","1,000 ohms",["10 ohms","100 ohms","10,000 ohms"],"Brown=1, black=0, red=x100, so 1,000 ohms.")
H('392.d.5.E',4,"A resistor's tolerance band that is gold means a tolerance of:","5 percent",["1 percent","10 percent","20 percent"],"Gold is 5%; silver is 10%.")
H('392.d.5.F',3,"Ohm's Law can be written V = I x R. Solving for current gives:","I = V / R",["I = V x R","I = R / V","I = V + R"],"Divide both sides by R.")
H('392.d.5.F',4,"A 12 V source drives current through a 4 ohm resistor. What is the current?","3 amps",["48 amps","8 amps","0.33 amps"],"I = 12 / 4 = 3 A.")
H('392.d.5.G',3,"Power in watts equals voltage times:","current",["resistance","time","frequency"],"P = V x I.")
H('392.d.5.G',4,"A device draws 2 amps from a 120 volt outlet. Its power is:","240 watts",["60 watts","122 watts","118 watts"],"P = 120 x 2 = 240 W.")
H('392.d.5.H',3,"In a series circuit, the current is the same:","through every component",["only in the first part","only in the last part","in none of the parts"],"Series elements share one path.")
H('392.d.5.H',4,"In a parallel circuit, the voltage across each branch is:","the same",["divided equally","zero","different for each"],"Parallel branches connect to the same two nodes.")
H('392.d.5.I',3,"A 100 ohm resistor carries 0.2 amps. The voltage across it is:","20 volts",["500 volts","0.002 volts","100.2 volts"],"V = 0.2 x 100 = 20 V.")
H('392.d.5.I',4,"Two 10 ohm resistors in series are connected to a 20 V source. The current is:","1 amp",["2 amps","4 amps","0.5 amps"],"Total R = 20 ohms, so I = 1 A.")
H('392.d.5.J',3,"A 5 ohm resistor carries 2 amps. The power dissipated is:","20 watts",["10 watts","7 watts","50 watts"],"P = I^2 x R = 4 x 5 = 20 W.")
H('392.d.5.J',4,"A 60 watt bulb runs on 120 volts. The current is:","0.5 amps",["2 amps","7200 amps","60 amps"],"I = P / V = 60 / 120 = 0.5 A.")
H('392.d.5.K',3,"A current of 0.005 amps written in scientific notation is:","5 x 10^-3 amps",["5 x 10^3 amps","5 x 10^-2 amps","0.5 x 10^-3 amps"],"0.005 = 5 x 10^-3.")
H('392.d.5.K',4,"A resistance of 4,700 ohms is written in engineering notation as:","4.7 kilohms",["47 kilohms","0.47 kilohms","4.7 megohms"],"4,700 = 4.7 x 10^3 = 4.7 k.")

H('392.d.6.A',3,"In alternating current (AC), the direction of flow:","reverses periodically",["never changes","stops permanently","moves in one direction"],"AC alternates direction.")
H('392.d.6.A',4,"Household electricity in the United States is AC with a frequency of:","60 hertz",["50 hertz","120 hertz","6 hertz"],"U.S. power is 60 Hz.")
H('392.d.6.B',3,"A sine wave has a peak voltage of 10 V. Its peak-to-peak voltage is:","20 volts",["5 volts","10 volts","14.1 volts"],"Peak-to-peak is twice the peak.")
H('392.d.6.B',4,"The RMS value of a sine wave with a 100 V peak is about:","70.7 volts",["63.7 volts","141 volts","200 volts"],"RMS = 0.707 x peak.")
H('392.d.6.C',3,"When more mechanical load is placed on a generator, the current it supplies generally:","increases",["decreases","falls to zero","stays unchanged"],"More load means more current drawn and more torque required.")
H('392.d.6.C',4,"A generator turning harder when you plug in more devices shows that more electrical load requires more:","mechanical input power",["insulation","silence","sunlight"],"Output power must be supplied by the shaft.")
H('392.d.6.D',3,"A transformer is used to:","step AC voltage up or down",["convert AC to DC","store energy","create current"],"Transformers change AC voltage levels.")
H('392.d.6.D',4,"A transformer works only with:","alternating current",["direct current","static","chemical energy"],"A changing field is needed to induce voltage.")
H('392.d.6.E',3,"A transformer has 100 primary turns and 200 secondary turns. With 10 V on the primary, the secondary voltage is:","20 volts",["5 volts","10 volts","200 volts"],"Voltage scales with the turns ratio (2:1).")
H('392.d.6.E',4,"A step-down transformer has a 10:1 turns ratio. If the primary is 120 V, the secondary is:","12 volts",["1,200 volts","110 volts","10 volts"],"120 / 10 = 12 V.")
H('392.d.6.F',3,"Capacitance is measured in units called:","farads",["henrys","ohms","watts"],"The farad is the unit of capacitance.")
H('392.d.6.F',4,"As the frequency of an AC signal increases, capacitive reactance:","decreases",["increases","becomes infinite","is unchanged"],"Xc = 1 / (2 pi f C).")
H('392.d.6.G',3,"Inductance is measured in units called:","henrys",["farads","ohms","coulombs"],"The henry is the unit of inductance.")
H('392.d.6.G',4,"When the frequency of an AC signal goes up, inductive reactance:","rises",["falls","becomes zero","is unchanged"],"XL = 2 pi f L.")

H('392.d.7.A',3,"Kirchhoff's voltage law states that the sum of voltages around a closed loop is:","zero",["infinite","one","equal to current"],"Voltage rises equal voltage drops around a loop.")
H('392.d.7.A',4,"Kirchhoff's current law states that the current entering a junction equals the current:","leaving it",["created in it","lost in it","stored in it"],"Charge is conserved at a node.")
H('392.d.7.B',3,"To build a parallel circuit on a breadboard, components are connected so that:","each has its own path across the source",["all share one path","only one is connected","none touch the source"],"Parallel branches each connect across the supply.")
H('392.d.7.B',4,"Before powering up a circuit you have built, you should first:","check connections against the schematic",["connect it to mains","skip the check","remove the resistors"],"Verification prevents damage.")
H('392.d.7.C',3,"Moving a magnet through a coil of wire induces a:","voltage",["mass","sound only","fuel"],"Electromagnetic induction creates voltage.")
H('392.d.7.C',4,"Faraday's law says that the induced voltage in a coil depends on how fast the:","magnetic field changes",["wire's color changes","resistance is painted","coil is named"],"Induced emf is proportional to the rate of flux change.")
H('392.d.7.D',3,"A good first step in troubleshooting a dead circuit is to:","check the power source",["replace every part","throw it away","guess"],"Start with the simplest, most common cause.")
H('392.d.7.D',4,"Dividing a faulty circuit into sections and testing each is called:","half-split troubleshooting",["random testing","brute-force wiring","guess-and-replace"],"Splitting narrows down the fault quickly.")
H('392.d.7.E',3,"A component with two leads that stores charge between plates is a:","capacitor",["resistor","diode","fuse"],"Capacitors store charge on plates.")
H('392.d.7.E',4,"A component marked with a band at one end that allows current in one direction only is a:","diode",["capacitor","inductor","resistor"],"The band marks the diode's cathode.")
H('392.d.7.F',3,"Torque in a DC motor is produced when current in the armature interacts with a:","magnetic field",["gravity field","water","light beam"],"Current in a magnetic field feels a force.")
H('392.d.7.F',4,"Increasing the current through a motor's armature generally makes its torque:","increase",["decrease","vanish","reverse"],"Torque is proportional to armature current.")
H('392.d.7.G',3,"Counter electromotive force (CEMF) in a motor is produced because:","the spinning armature acts like a generator",["the motor is too cold","the brushes are painted","the housing is plastic"],"Motion in a field induces an opposing voltage.")
H('392.d.7.G',4,"As a motor speeds up, its CEMF increases, which causes the armature current to:","decrease",["increase","double","remain at a maximum"],"Higher CEMF reduces net voltage across the armature.")

H('392.d.8.A',3,"To measure current in a series circuit, a meter must be connected:","in series with the circuit",["across the source","in parallel with each part","outside the loop"],"Ammeters are placed in the current path.")
H('392.d.8.A',4,"To measure the voltage drop across a resistor, connect the voltmeter:","in parallel with it",["in series with it","after the load","only to ground"],"Voltmeters connect across components.")
H('392.d.8.B',3,"A generator works on the principle of:","electromagnetic induction",["chemical reaction","friction heat","gravity feed"],"Moving conductors in a field induce voltage.")
H('392.d.8.B',4,"Transformers lose some energy as heat in the:","core and windings",["case paint","label","plug cover"],"Core and winding losses produce heat.")
H('392.d.8.C',3,"A simple voltage divider is built from two:","resistors",["diodes","switches","wires only"],"Two series resistors divide voltage.")
H('392.d.8.C',4,"To limit current through an LED powered from a battery, a designer adds a:","series resistor",["second battery","parallel capacitor","bigger LED"],"The resistor sets a safe current.")

H('392.d.9.A',3,"When stripping wire, the tool should be pointed:","away from your body",["toward your hand","at a classmate","upward at your face"],"Point tools away to avoid injury.")
H('392.d.9.A',4,"Hot-air rework tools should be used:","with ventilation and eye protection",["without any guard","in a closed box","with wet hands"],"Heat and fumes require protection.")
H('392.d.9.B',3,"An oscilloscope is a precision instrument used to display:","voltage changes over time",["room temperature","wire color","resistor price"],"Scopes plot voltage versus time.")
H('392.d.9.B',4,"A bench power supply with a current limit protects a circuit by:","capping the current delivered",["removing the load","raising the voltage","bypassing ground"],"Current limiting protects against faults.")
H('392.d.9.C',3,"A voltmeter is connected across a component, while an ammeter is connected:","in series with the component",["across the component","after the ground","outside the circuit"],"Ammeters must carry the circuit current.")
H('392.d.9.C',4,"Placing an ammeter in parallel across a power source can:","cause a short circuit",["measure voltage safely","double the voltage","cool the circuit"],"Ammeters have very low resistance.")
H('392.d.9.D',3,"Before measuring resistance of a part in a circuit, you should:","remove power from the circuit",["apply more voltage","touch both leads together","switch to AC voltage"],"Ohmmeters supply their own current.")
H('392.d.9.D',4,"Setting a multimeter to the ohms range and touching probes together should read about:","zero ohms",["infinite ohms","one megohm","120 ohms"],"Shorted probes have near-zero resistance.")
H('392.d.9.E',3,"The time for one complete cycle of a waveform is its:","period",["amplitude","phase","gain"],"Period is the duration of one cycle.")
H('392.d.9.E',4,"If one cycle of a signal spans 4 divisions at 1 ms per division, the period is:","4 milliseconds",["0.25 milliseconds","1 millisecond","40 milliseconds"],"4 divisions x 1 ms = 4 ms.")
H('392.d.9.F',3,"Circuit simulation software lets designers:","test a design before building it",["avoid understanding circuits","replace all labs forever","damage real parts"],"Simulation finds problems early.")
H('392.d.9.F',4,"A SPICE program is commonly used to:","simulate circuit behavior",["edit photographs","design logos","write novels"],"SPICE is a circuit simulator.")
H('392.d.9.G',3,"Measured values in a lab notebook should always include:","units",["jokes","doodles","guesses"],"A number without units is incomplete.")
H('392.d.9.G',4,"Recording a test circuit's observations in a notebook helps the team later to:","reproduce and troubleshoot results",["forget details","hide errors","avoid retesting"],"Records make results repeatable.")

H('392.d.10.A',3,"On a schematic, reference designators like R1 and C2 identify:","individual components",["the wire lengths","the board owner","the schematic's age"],"Designators label each part.")
H('392.d.10.A',4,"On a schematic, signal flow is conventionally drawn from:","left to right",["right to left","bottom to top","center outward"],"Inputs on the left, outputs on the right.")
H('392.d.10.B',3,"Adding a fuse to a design improves:","safety",["noise","price","weight"],"Fuses protect against overcurrent.")
H('392.d.10.B',4,"Using components rated above the expected load improves a design's:","reliability",["packaging","paint","marketing"],"Derating extends component life.")
H('392.d.10.C',3,"If a circuit draws too much current, a designer could improve it by:","increasing resistance",["removing the resistor","shorting the load","removing the fuse"],"Higher resistance lowers current.")
H('392.d.10.C',4,"A bypass capacitor placed near an IC helps reduce:","power supply noise",["board size","cost of ICs","pin count"],"Bypass caps filter supply noise.")
H('392.d.10.D',3,"When sketching a schematic, components are drawn using:","standard symbols",["photographs","random shapes","company logos"],"Standard symbols let everyone read the drawing.")
H('392.d.10.D',4,"A neat schematic sketch minimizes crossing wires to make it:","easier to read",["harder to follow","more expensive","heavier"],"Clean layouts reduce confusion.")
H('392.d.10.E',3,"Flexible, printable electronics are an example of:","an emerging technology",["an obsolete method","a hand tool","a safety law"],"New fabrication methods are emerging.")
H('392.d.10.E',4,"The Internet of Things (IoT) refers to everyday objects that:","connect to a network and share data",["run without power","are made of paper","cannot be programmed"],"IoT devices are networked.")

H('392.d.11.A',3,"A prototype is:","a first working model of a design",["the final sales ad","a broken part","a shipping label"],"Prototypes are early test versions.")
H('392.d.11.A',4,"Building a breadboard version before making a printed circuit board allows the designer to:","test and change the design cheaply",["skip testing","avoid parts","sell it at once"],"Breadboards are easy to modify.")
H('392.d.11.B',3,"To join electronic components to a circuit board, a technician uses:","a soldering iron",["a paintbrush","a hammer","a tape measure"],"Soldering makes the electrical joints.")
H('392.d.11.B',4,"Which tool is used to remove insulation from a wire without cutting the conductor?","Wire stripper",["Hacksaw","Tin snips","Pry bar"],"Strippers are sized to the wire gauge.")
H('392.d.11.C',3,"A final project presentation might include:","a working demonstration",["a blank poster","no explanation","a hidden board"],"Demos show the product works.")
H('392.d.11.C',4,"To answer audience questions about a project, a presenter should:","refer to test data and notes",["avoid eye contact","guess answers","skip the questions"],"Data supports credible answers.")

# ---------------- 393: Electronics II ----------------
H('393.d.1.A',3,"A two-year degree in electronics technology typically prepares a graduate to work as a:","technician",["judge","surgeon","chef"],"Associate programs prepare technicians.")
H('393.d.1.A',4,"Which path usually allows an electronics worker to advance from technician to design engineer?","Earning a bachelor's degree",["Skipping training","Avoiding certifications","Leaving the field"],"Engineering roles generally require a four-year degree.")
H('393.d.1.B',3,"Which employer would hire an electronics technician?","A telecommunications company",["A flower shop","A shoe store","A barber shop"],"Telecom companies rely on electronics technicians.")
H('393.d.1.B',4,"A field service technician repairs electronic equipment:","at customer locations",["only in space","only underwater","at no location"],"Field techs travel to customers.")
H('393.d.1.C',3,"Industry certifications help job seekers by:","proving verified skills to employers",["replacing all experience","guaranteeing a raise","removing exams"],"Certifications provide credible proof of skill.")
H('393.d.1.C',4,"The Certified Electronics Technician (CET) credential is awarded after passing:","a standardized exam",["a cooking test","a driving test","a spelling bee"],"CET requires a standardized exam.")
H('393.d.1.D',3,"Professional etiquette when communicating with a customer about a repair includes:","being courteous and honest",["using slang only","hiding costs","ignoring questions"],"Courtesy and honesty build trust.")
H('393.d.1.D',4,"Charging a customer for repairs that were not done is:","unethical and illegal",["standard practice","good business","a safety rule"],"Billing for work not done is fraud.")
H('393.d.1.E',3,"A workplace that welcomes people of all backgrounds is described as:","inclusive",["exclusive","closed","isolated"],"Inclusive workplaces welcome everyone.")
H('393.d.1.E',4,"Making a coworker feel included on a technical team can improve:","collaboration and trust",["delays","confusion","secrecy"],"Inclusion strengthens teamwork.")
H('393.d.1.F',3,"If you witness workplace discrimination, an appropriate action is to:","report it to a supervisor or HR",["laugh","post gossip","do nothing and hide"],"Reporting lets the employer address it.")
H('393.d.1.F',4,"A company that ignores repeated discrimination complaints may face:","lawsuits and fines",["tax refunds","free advertising","awards"],"Employers are liable for ignoring discrimination.")
H('393.d.1.G',3,"Career and technical education (CTE) programs in electronics help students:","prepare for jobs or further study",["avoid all labs","skip math","stay home"],"CTE builds job-ready skills.")
H('393.d.1.G',4,"A dual-credit electronics course allows a high school student to earn:","high school and college credit",["only a trophy","only a lunch pass","a driver's license"],"Dual credit counts toward both levels.")
H('393.d.1.H',3,"A cooperative education (co-op) program combines classroom study with:","paid work experience",["unpaid vacations","video games","free time"],"Co-ops pair school with work.")
H('393.d.1.H',4,"Student organizations like SkillsUSA help students develop:","leadership and technical skills",["only sports skills","cooking skills only","no new skills"],"SkillsUSA builds career skills.")
H('393.d.1.I',3,"ABET stands for the Accreditation Board for Engineering and:","Technology",["Tourism","Trade","Transport"],"The T in ABET stands for Technology.")
H('393.d.1.I',4,"A degree from an ABET-accredited program is often required to pursue:","a professional engineering license",["a pilot's medal","a black belt","a library card"],"Licensure boards often require accredited degrees.")

H('393.d.2.A',3,"In designing a complex electronic product, hardware and software teams must:","coordinate their work",["work in secret","avoid meetings","duplicate efforts"],"Integrated products need coordination.")
H('393.d.2.A',4,"A team that shares test results openly is more likely to:","find and fix defects early",["hide defects","miss deadlines","repeat mistakes"],"Openness speeds problem finding.")
H('393.d.2.B',3,"One principle of effective team problem solving is to:","focus on the problem, not the person",["blame the newest member","avoid facts","ignore deadlines"],"Blame-free analysis finds causes.")
H('393.d.2.B',4,"Assigning clear responsibilities on a team prevents:","duplicated or missed tasks",["all progress","communication","documentation"],"Clear roles avoid overlap and gaps.")
H('393.d.2.C',3,"A team member shows a proper attitude by:","meeting commitments",["missing deadlines","avoiding feedback","blaming others"],"Reliability builds team trust.")
H('393.d.2.C',4,"A team leader should handle a team member's mistake by:","coaching privately and constructively",["embarrassing them publicly","ignoring all errors","firing at once"],"Constructive coaching helps people improve.")

H('393.d.3.A',3,"During the planning phase of a project, a team defines its scope, schedule, and:","budget",["lunch","mascot","slogan"],"Planning sets scope, time, and cost.")
H('393.d.3.A',4,"Monitoring a project means:","tracking progress against the plan",["ignoring the plan","starting a new project","hiding results"],"Monitoring compares actual to planned.")
H('393.d.3.B',3,"A milestone in a project schedule marks:","a significant completed point",["a lunch break","an employee birthday","a random delay"],"Milestones show key achievements.")
H('393.d.3.B',4,"The sequence of tasks that determines the shortest possible project duration is the:","critical path",["longest wire","main street","short circuit"],"Delays on the critical path delay the project.")
H('393.d.3.C',3,"Operating a simulated electronics company gives students experience in:","production and marketing roles",["only repairing cars","no business skills","only sports"],"Simulated firms mirror real company functions.")
H('393.d.3.C',4,"In a student-run enterprise, quality control staff are responsible for:","inspecting products before sale",["setting prices only","hiring the teacher","buying lunches"],"QC checks products meet standards.")
H('393.d.3.D',3,"Before building a product, a production plan should include a:","list of required materials and steps",["guess at success","coin toss","random sketch"],"Plans list materials and procedures.")
H('393.d.3.D',4,"Estimating how long each assembly step takes helps a planner to set:","a realistic production schedule",["a company logo","a color theme","a price tag only"],"Time estimates drive scheduling.")

H('393.d.4.A',3,"A work order for a repair typically records the customer's request, the work done, and:","parts used",["the weather","the technician's pets","the stock price"],"Work orders document labor and parts.")
H('393.d.4.A',4,"Completed work orders are kept as records to:","document services and costs",["avoid billing","hide mistakes","reduce quality"],"Records support billing and accountability.")
H('393.d.4.B',3,"Which factor most directly affects the cost of manufacturing an electronic device?","Cost of components and labor",["The name of the product","The color of the box only","The CEO's age"],"Parts and labor drive manufacturing cost.")
H('393.d.4.B',4,"Ordering components in larger quantities often lowers the cost per part because of:","volume discounts",["inflation","tariffs only","delays"],"Suppliers discount bulk orders.")
H('393.d.4.C',3,"A project budget estimates:","the total cost of materials and labor",["only the profit","only the weight","the end date only"],"Budgets forecast project costs.")
H('393.d.4.C',4,"If a project's actual costs exceed its budget, the team should:","identify the cause and adjust the plan",["ignore the overrun","hide the numbers","double the scope"],"Variance analysis leads to corrective action.")
H('393.d.4.D',3,"A production schedule helps a company make sure orders are:","completed on time",["never filled","delayed on purpose","lost"],"Schedules coordinate delivery.")
H('393.d.4.D',4,"Scheduling assembly steps in order of dependency means a step starts only after:","its prerequisite steps are done",["everything else is lost","it is canceled","the product ships"],"Dependent tasks wait for their predecessors.")
H('393.d.4.E',3,"A patent protects an inventor's:","invention from being copied",["lunch hours","office space","pay rate"],"Patents give exclusive rights to an invention.")
H('393.d.4.E',4,"Using a copyrighted software library in a product without a license may violate:","copyright law",["gravity","zoning rules","tax tables"],"Software is protected by copyright.")
H('393.d.4.F',3,"A service manual often contains a schematic, a parts list, and:","troubleshooting steps",["recipes","jokes","poetry"],"Manuals guide repair work.")
H('393.d.4.F',4,"To read a technical drawing correctly, you must first understand its:","symbols and notes",["author's hobbies","paper brand","file date only"],"Symbols and notes carry the meaning.")

H('393.d.5.A',3,"Why do advanced electronics students still take safety tests?","Higher voltages and complex equipment add hazards",["Tests replace labs","Hazards disappear with skill","Tests are optional"],"Advanced work involves greater risks.")
H('393.d.5.A',4,"A passing safety test score shows that a student:","knows the rules for safe equipment use",["can ignore the rules","owns the lab","is an expert"],"It verifies safety knowledge.")
H('393.d.5.B',3,"Before servicing a power supply, the manual will tell you to:","disconnect it from mains power",["plug it in","spray it with water","remove the ground pin"],"De-energize before servicing.")
H('393.d.5.B',4,"Safety labels and instructions on equipment must be:","read and followed",["covered up","removed","ignored"],"Labels warn of real hazards.")
H('393.d.5.C',3,"OSHA's lockout/tagout standard is intended to prevent:","unexpected startup of equipment",["paint damage","slow payroll","noise complaints"],"LOTO protects workers during servicing.")
H('393.d.5.C',4,"The National Electrical Code (NEC) provides rules for:","safe electrical installations",["dress codes","traffic flow","menu planning"],"The NEC governs wiring safety.")
H('393.d.5.D',3,"Cathode ray tubes and fluorescent bulbs may contain:","lead or mercury",["gold bars","food dyes","cotton"],"Older electronics contain toxic metals.")
H('393.d.5.D',4,"Waste that is toxic, corrosive, ignitable, or reactive is classified as:","hazardous waste",["recyclable paper","general trash","compost"],"These traits define hazardous waste.")
H('393.d.5.E',3,"Lithium batteries should be taken to:","a battery recycling site",["the incinerator at home","a creek","the kitchen sink"],"Lithium cells can start fires if mishandled.")
H('393.d.5.E',4,"Hazardous waste records, called manifests, track waste from the generator to:","its final disposal site",["the cafeteria","the front office","a retail store"],"Manifests document cradle-to-grave handling.")
H('393.d.5.F',3,"A technician checks a soldering station's temperature setting regularly to:","ensure safe, quality joints",["lower the voltage","change wire color","add flux"],"Correct temperature prevents bad joints and damage.")
H('393.d.5.F',4,"Preventive maintenance is done:","on a regular schedule before failure",["only after failure","never","once at purchase"],"It prevents breakdowns.")
H('393.d.5.G',3,"An ESD wrist strap protects components by:","draining static charge safely",["building up charge","heating parts","adding voltage"],"The strap bleeds off static.")
H('393.d.5.G',4,"Moisture-sensitive ICs are often stored in sealed bags with:","desiccant",["water","oil","tape"],"Desiccant absorbs moisture.")
H('393.d.5.H',3,"Skipping scheduled maintenance on test equipment can result in:","inaccurate measurements",["improved accuracy","longer warranties","free repairs"],"Drift goes uncorrected without maintenance.")
H('393.d.5.H',4,"A technician who knowingly uses damaged safety equipment could be considered:","negligent",["careful","heroic","exempt"],"Knowingly ignoring hazards is negligence.")

H('393.d.6.A',3,"Mesh analysis uses which law to write equations for each loop?","Kirchhoff's voltage law",["Kirchhoff's current law","Faraday's law","Newton's law"],"Mesh equations sum loop voltages.")
H('393.d.6.A',4,"Nodal analysis is based on:","Kirchhoff's current law",["Kirchhoff's voltage law","Lenz's law","Boyle's law"],"Node equations sum currents at junctions.")
H('393.d.6.B',3,"In a purely resistive AC circuit, voltage and current are:","in phase",["90 degrees apart","opposite always","unrelated"],"Resistors do not shift phase.")
H('393.d.6.B',4,"In a series RC circuit, the time constant is found by multiplying:","resistance by capacitance",["voltage by current","power by time","inductance by frequency"],"Tau = R x C.")
H('393.d.6.C',3,"A voltage regulator is used to:","keep an output voltage steady",["raise noise","stop current","create energy"],"Regulators hold a constant output.")
H('393.d.6.C',4,"A Zener diode regulator works by operating the diode in:","reverse breakdown",["open circuit","forward bias only","saturation only"],"Zeners hold voltage in reverse breakdown.")
H('393.d.6.D',3,"A diode allows current to flow mainly when it is:","forward biased",["reverse biased","unpowered","overheated"],"Forward bias lets current pass.")
H('393.d.6.D',4,"A transistor used as a switch operates between cutoff and:","saturation",["induction","regulation","oscillation"],"Switching uses the off and fully-on states.")
H('393.d.6.E',3,"A rectifier circuit changes:","AC to pulsating DC",["DC to AC","light to sound","heat to current"],"Rectifiers convert AC to DC.")
H('393.d.6.E',4,"In a power supply, the filter capacitor reduces:","ripple voltage",["input power","wire size","diode count"],"Filtering smooths the rectified output.")
H('393.d.6.F',3,"In optoelectronics, a photodiode differs from an LED because it:","converts light into current",["emits light","stores charge","amplifies sound"],"Photodiodes detect light.")
H('393.d.6.F',4,"An optocoupler is used to:","electrically isolate two circuits",["join two circuits' grounds","amplify audio","heat a wire"],"Light carries the signal across an isolation gap.")
H('393.d.6.G',3,"In a transmission line, matching the load impedance to the line helps reduce:","signal reflections",["wire length","line color","antenna height"],"Mismatch reflects energy back.")
H('393.d.6.G',4,"Coaxial cable is used for radio signals mainly because it:","shields signals from interference",["generates interference","stores power","amplifies noise"],"The outer shield blocks noise.")
H('393.d.6.H',3,"The part of a computer chip that executes instructions is the:","CPU",["RAM","LED","ADC"],"The central processing unit runs instructions.")
H('393.d.6.H',4,"A microcontroller differs from a microprocessor because it typically includes:","memory and input/output on the same chip",["no memory","only a screen","a wireless charger"],"Microcontrollers are self-contained.")
H('393.d.6.I',3,"A switching power supply is more efficient than a linear supply because it:","switches transistors on and off rapidly",["burns off extra voltage as heat","uses larger resistors","avoids transformers"],"Switching wastes less power as heat.")
H('393.d.6.I',4,"Increasing the field strength in a DC motor without changing current makes the torque:","increase",["decrease","vanish","reverse constantly"],"Torque is proportional to field strength and current.")
H('393.d.6.J',3,"A technician measures 0 volts at the output of a regulator that has 12 volts at its input. The most likely fault is:","a failed regulator",["a good regulator","a brighter display","a full battery"],"Input present but no output points to the regulator.")
H('393.d.6.J',4,"Intermittent faults are often found by:","flexing or tapping the board while monitoring signals",["replacing the whole product","waiting for failure","ignoring symptoms"],"Mechanical stress reveals bad joints.")

H('393.d.7.A',3,"When using a hot-air station, a technician should keep the nozzle away from:","flammable materials",["the work area light","the test leads","the tool stand"],"Hot air can ignite nearby materials.")
H('393.d.7.A',4,"Working on energized equipment above 50 volts requires that technicians be:","trained and use proper protective gear",["unsupervised","wearing jewelry","using wet tools"],"Higher voltages are dangerous.")
H('393.d.7.B',3,"A logic analyzer is used to examine:","digital signals",["body temperature","paint thickness","water quality"],"Logic analyzers capture digital states.")
H('393.d.7.B',4,"A spectrum analyzer displays signal strength versus:","frequency",["wire gauge","paint color","shelf life"],"Spectrum analyzers show amplitude across frequency.")
H('393.d.7.C',3,"A scope probe set to 10x reduces the signal at the scope by a factor of:","ten",["two","hundred","one thousand"],"A 10x probe attenuates by ten.")
H('393.d.7.C',4,"To avoid damaging a circuit when measuring with an analog meter, you should start on:","the highest range",["the lowest range","a random range","the resistance range"],"Start high, then reduce range.")
H('393.d.7.D',3,"A transient simulation shows how a circuit's voltages change over:","time",["color","cost","distance"],"Transient analysis plots values versus time.")
H('393.d.7.D',4,"Before trusting a simulation result, a designer should:","compare it with real measurements",["ignore the model","avoid tests","delete the file"],"Models must be validated.")
H('393.d.7.E',3,"The component that stores data permanently in a computer, even when power is off, is the:","hard drive or SSD",["RAM chip","cooling fan","power cord"],"Drives are non-volatile storage.")
H('393.d.7.E',4,"The motherboard's main role is to:","connect and allow communication among components",["store the monitor","produce power","protect from viruses"],"The motherboard links the parts.")

H('393.d.8.A',3,"A schematic page divided into functional blocks, such as power and control sections, is easier to:","read and troubleshoot",["lose","erase","print"],"Block organization aids understanding.")
H('393.d.8.A',4,"On a multi-sheet schematic, off-page connectors show that a net:","continues on another sheet",["ends at the page edge","is broken","is grounded"],"Off-page connectors link sheets.")
H('393.d.8.B',3,"Using redundant power supplies in critical equipment is a way to design in:","reliability",["clutter","noise","weight"],"Redundancy keeps systems running.")
H('393.d.8.B',4,"Adding overvoltage protection to a design primarily improves:","safety and reliability",["only appearance","only cost","only weight"],"Protection prevents damage and hazards.")
H('393.d.8.C',3,"Replacing a bulky linear regulator with a switching regulator can improve a product's:","efficiency",["fragility","heat output","weight"],"Switchers waste less power.")
H('393.d.8.C',4,"Customer complaints about short battery life suggest a redesign focused on:","lower power consumption",["brighter paint","louder buttons","bigger logos"],"Reducing consumption extends battery life.")
H('393.d.8.D',3,"Industry-standard schematics use symbols defined by organizations such as:","IEEE and IEC",["NFL and NBA","USDA and FDA","NASA and NATO"],"IEEE and IEC publish symbol standards.")
H('393.d.8.D',4,"A title block on a schematic typically includes the drawing's name, date, and:","revision number",["lunch order","phone ringtone","weather"],"Revision control is part of the title block.")
H('393.d.8.E',3,"Before filing for a patent, an inventor usually performs a:","prior art search",["cooking class","tax audit","weather study"],"The search checks whether the idea is new.")
H('393.d.8.E',4,"In the U.S., patent applications are filed with the:","Patent and Trademark Office",["Postal Service","Weather Service","Forest Service"],"The USPTO examines patents.")
H('393.d.8.F',3,"Designers use CAD software to lay out a printed circuit board by placing parts and:","routing traces",["cooking meals","painting walls","adding ads"],"Traces connect component pads.")
H('393.d.8.F',4,"Before ordering a printed circuit board, a designer runs a design rule check to find:","spacing and connection errors",["spelling mistakes","price changes","color issues"],"DRC catches layout errors.")
H('393.d.8.G',3,"Wireless power transfer, such as charging a phone without a cable, is an example of:","an innovative technology",["an outdated method","a hand tool","a fuse type"],"Wireless charging is a newer approach.")
H('393.d.8.G',4,"Wearable electronics are an emerging field because they combine sensors with:","small, low-power electronics",["large heavy tubes","steam engines","unpowered paper"],"Wearables need compact, efficient circuits.")

H('393.d.9.A',3,"After designing a circuit and building a prototype, the next step is to:","test it against requirements",["sell it immediately","discard the design","stop work"],"Testing checks the prototype meets requirements.")
H('393.d.9.A',4,"Prototypes are built in stages, such as breadboard, perfboard, and then:","a printed circuit board",["a final sale","a drawing only","a lunch table"],"PCBs are the refined stage.")
H('393.d.9.B',3,"A reflow oven is used to:","solder surface-mount parts",["paint boards","cut wire","drill metal"],"Reflow melts solder paste.")
H('393.d.9.B',4,"For fine surface-mount work, a technician often uses:","a microscope and tweezers",["a sledgehammer","a ladder","a garden hose"],"Small parts need magnification and precision.")
H('393.d.9.C',3,"When presenting a prototype to a panel, you should be prepared to:","explain design choices and test results",["avoid questions","skip the demo","hide failures"],"Panels expect justification and data.")
H('393.d.9.C',4,"A prototype demonstration is most convincing when it:","shows the product meeting its stated requirements",["hides its limits","has no data","is delayed"],"Meeting requirements proves success.")

H('391.d.9.G',4,"Which pictorial drawing type shows the front face in true shape, with depth lines drawn at an angle?","Oblique drawing",["Isometric drawing","Orthographic drawing","Section drawing"],"Oblique drawings keep the front face undistorted.")
H('392.d.5.G',4,"A heater is rated 1,200 watts at 120 volts. How much current does it draw?","10 amps",["1,320 amps","0.1 amps","144,000 amps"],"I = P / V = 1200 / 120 = 10 A.")
H('393.d.3.A',4,"Which project management phase involves the team doing the work described in the plan?","Executing",["Initiating","Closing","Planning"],"Executing carries out the plan.")
H('393.d.5.F',4,"Which routine task keeps a bench power supply's readings trustworthy?","Periodic calibration",["Painting the case","Unplugging daily","Swapping knobs"],"Calibration verifies accuracy.")

B.balance()
